                return 0
            return value

        class UserSchema(Schema):
            age = fields.Int(pre_load=handle_none, allow_none=True)

        schema = UserSchema()
        result = schema.load({"age": None})
        assert result["age"] == 0

    def test_field_post_load_not_called_with_none_input_when_not_allowed(self):
        def handle_none(value):
            if value is None:
