        class UserSchema(Schema):
            age = fields.Int(post_load=handle_none, allow_none=False)

        schema = UserSchema()
        with pytest.raises(ValidationError) as exc:
            schema.load({"age": None})
        assert exc.value.messages == {"age": ["Field may not be null."]}

